// Helper to compute binomial coefficients
ll binomial(ll n, ll k) {
    if (k < 0 || k > n) return 0;
    if (k == 0 || k == n) return 1;
    if (C[n][k] != -1) return C[n][k];
    return C[n][k] = binomial(n-1, k-1) + binomial(n-1, k);
}

