    vector<vector<ll>> grid(n, vector<ll>(n, 0));
    for (ll i = 0; i < n; i++) {
        for (ll j = 0; j < n; j++) {
            if (i >= R-1 && j >= R-1) {
                ll a = 1, b = 1;
                for (ll k = 0; k < R-1; k++) {
                    a = a * (i - k) / (k + 1);
                    b = b * (j - k) / (k + 1);
                }
                grid[i][j] = a * b;
            }
        }
    }

    // Prefix sum
    vector<vector<ll>> pref(n+1, vector<ll>(n+1, 0));
    for (ll i = 1; i <= n; i++) {
        for (ll j = 1; j <= n; j++) {
            pref[i][j] = pref[i][j-1] + pref[i-1][j] - pref[i-1][j-1] + grid[i-1][j-1];
        }
    }

    // Suffix sum
    vector<vector<ll>> suff(n+1, vector<ll>(n+1, 0));
    for (ll i = 0; i <= n; i++) {
        for (ll j = 0; j <= n; j++) {
            suff[i][j] = pref[n][n] - pref[n-i][n] - pref[n][n-j] + pref[n-i][n-j];
        }
    }

    ll d = min(2*n - 1, n + R - 2);

    // DP arrays using unordered_map for memory efficiency
    vector<vector<unordered_map<ll, ll>>> fdp(n+1, vector<unordered_map<ll, ll>>(n+1));
    vector<vector<unordered_map<ll, ll>>> bdp(n+1, vector<unordered_map<ll, ll>>(n+1));

    fdp[0][0][0] = 1;
    bdp[0][0][0] = 1;

    ll target_val = sols[R][C];
    ll total_area = pref[n][n];
    ll first_half = (-target_val + total_area) / 2;
    ll second_half = total_area - first_half;
    ll solution_count = 0;

    // Traverse the grid
    for (ll step = 0; step <= n; step++) {
        // Horizontal extensions
        for (ll col = 0; col < n; col++) {
            ll idx = step + col;
            if (idx + 1 <= d && path[idx] != 'B' && step <= n && col < n) {
                for (auto& kv : fdp[step][col]) {
                    ll new_area = kv.first + (pref[n][col+1] - pref[step][col+1]);
                    if (new_area <= second_half) {
                        fdp[step][col+1][kv.first] += kv.second;
                    }
                }
            }
            if (idx + 1 <= 2*n - d && path[2*n - idx - 2] != 'B' && step <= n && col < n) {
                for (auto& kv : bdp[step][col]) {
                    ll new_area = suff[n][n] - kv.first - suff[n-step][n-(col+1)];
                    if (new_area <= second_half) {
                        bdp[step][col+1][kv.first] += kv.second;
                    }
                }
            }
        }

        if (step < n) {
            // Vertical extensions
            for (ll col = 0; col <= n; col++) {
                ll idx = step + col;
                if (idx + 1 <= d && path[idx] != 'A' && step < n) {
                    ll delta = pref[step+1][col] - pref[step][col];
                    for (auto& kv : fdp[step][col]) {
                        ll area = kv.first + delta;
                        ll remainder = pref[step+1][n] - area;
                        if (remainder <= second_half) {
                            fdp[step+1][col][area] += kv.second;
                        }
                    }
                }
                if (idx + 1 <= 2*n - d && path[2*n - idx - 2] != 'A' && step < n) {
                    ll delta = suff[n-step][n-col] - suff[n-step-1][n-col];
                    for (auto& kv : bdp[step][col]) {
                        if (kv.first + delta <= second_half) {
                            bdp[step+1][col][kv.first + delta] += kv.second;
                        }
                    }
                }
                if (idx + 1 <= d) fdp[step][col].clear();
                if (idx + 1 <= 2*n - d) bdp[step][col].clear();
            }
        }
    }

    // Combine results
    for (ll i = 0; i <= n; i++) {
        ll j = d - i;
        if (j < 0 || j > n) continue;
        for (auto& kv : fdp[i][j]) {
            ll area = kv.first;
            ll freq = kv.second;
            solution_count += freq * bdp[n-i][n-j][first_half - area];
            if (first_half != second_half) {
                solution_count += freq * bdp[n-i][n-j][second_half - area];
            }
        }
    }

    cout << solution_count << endl;

    return 0;
}
